      else

        sprintf(s, "/sbin/route add default gw %s dev %s", gw, *this); //attacker controlled gw string

      system(s);

      sprintf(s, "/sbin/route add -net 224.0.0.0 netmask 224.0.0.0 gw %s dev %s", gw, *this); //attacker controlled gw string

      system(s);

